import assert from 'node:assert/strict';
import {Session} from 'node:inspector/promises';
import {readFileSync,writeFileSync} from 'node:fs';
import {compileWorker} from './shadow/tools/parity/parity.ts';
const base='/tmp/engine-post-prefix-profile-20261106',mode=process.argv[2],cell=Number(process.argv[3]??61),p=new Session();p.connect();
assert(['cpu','allocation'].includes(mode));
if(mode==='cpu'){await p.post('Profiler.enable');await p.post('Profiler.setSamplingInterval',{interval:250});}
else await p.post('HeapProfiler.enable');
const rows=[],cellRef=JSON.parse(readFileSync(base+'/shadow/tools/parity/cells.json','utf8')).cells[cell];
const probe=(globalThis as any).__compileProbe={rep:-5,async start(){
 if(mode==='cpu')await p.post('Profiler.start');
 else await p.post('HeapProfiler.startSampling',{samplingInterval:16384,includeObjectsCollectedByMajorGC:true,includeObjectsCollectedByMinorGC:true});
},async stop(scope:any){
 const {profile}=await p.post(mode==='cpu'?'Profiler.stop':'HeapProfiler.stopSampling') as any;
 if(mode==='cpu')assert(profile.startTime<=scope.scopeStart&&scope.scopeEnd<=profile.endTime,'CPU sample timestamps and hrtime must share a monotonic clock');
 writeFileSync(`${base}/${mode}-${cell}-${probe.rep}.json`,JSON.stringify({scope,profile}));
}};
for(probe.rep=-5;probe.rep<(mode==='cpu'?3:2);probe.rep++){
 await compileWorker(cell,base+'/worker.json');
 const r=JSON.parse(readFileSync(base+'/worker.json','utf8'));
 assert.equal(r.trackHash,cellRef.trackHash);assert.equal(r.physicalFrames,cellRef.physicalFrames);
 rows.push({rep:probe.rep,compileMs:r.compileMs,cpuMs:r.compileCpuMs,trackHash:r.trackHash,physicalFrames:r.physicalFrames});
}
p.disconnect();writeFileSync(`${base}/${mode}-${cell}-iterations.json`,JSON.stringify(rows,null,2)+'\n');
console.log(`${mode} cell${cell}: all exact, scoped profile saved`);

