import json,pathlib,collections
b=pathlib.Path('/tmp/engine-post-prefix-profile-20261106'); out={}
for mode in ['cpu','allocation']:
 total=collections.Counter();inclusive=collections.Counter();scopes=[]
 for p in sorted(b.glob(mode+'-61-[0-9].json')):
  d=json.loads(p.read_text());s=d['scope'];pr=d['profile'];scopes.append(s)
  def key(cf):return cf.get('functionName','')+' '+cf.get('url','').replace(str(b/'shadow')+'/','')+':'+str(cf.get('lineNumber',-1)+1)
  if mode=='cpu':
   nodes={n['id']:n for n in pr['nodes']};parent={c:n['id'] for n in pr['nodes'] for c in n.get('children',[])}; t=pr['startTime']
   for id,dt in zip(pr['samples'],pr['timeDeltas']):
    end=t+dt;w=max(0,min(end,s['scopeEnd'])-max(t,s['scopeStart']));t=end
    if not w:continue
    total[key(nodes[id]['callFrame'])]+=w/1000
    seen=set()
    while id:
     k=key(nodes[id]['callFrame'])
     if k not in seen:inclusive[k]+=w/1000;seen.add(k)
     id=parent.get(id)
  else:
   def walk(n):
    k=key(n['callFrame']);total[k]+=n['selfSize'];v=n['selfSize']+sum(walk(c) for c in n.get('children',[]));inclusive[k]+=v;return v
   walk(pr['head'])
 out[mode]={'units':'ms' if mode=='cpu' else 'bytes','scopes':scopes,'total':sum(total.values()),'self':total.most_common(),'inclusive':inclusive.most_common()}
 print(mode,'total',out[mode]['total'],'profiles',len(scopes));print('\n'.join(f'{v:12.1f} {k}' for k,v in total.most_common(35)))
(b/'summary.json').write_text(json.dumps(out,indent=2)+'\n')
